console.assert(lastCall === 'failure', `Expected 'failure', got '${lastCall}'`);

observeApiError(null, mockObserver);
console.assert(lastCall === 'failure', `Expected 'failure', got '${lastCall}'`);

observeApiError('', mockObserver);
console.assert(lastCall === 'failure', `Expected 'failure', got '${lastCall}'`);

// Test 4xx
observeApiError({ status: 400 }, mockObserver);
console.assert(lastCall === '4xx', `Expected '4xx', got '${lastCall}'`);

observeApiError({ status: 404 }, mockObserver);
console.assert(lastCall === '4xx', `Expected '4xx', got '${lastCall}'`);

observeApiError({ status: 499 }, mockObserver);
console.assert(lastCall === '4xx', `Expected '4xx', got '${lastCall}'`);

// Test 5xx
observeApiError({ status: 500 }, mockObserver);
console.assert(lastCall === '5xx', `Expected '5xx', got '${lastCall}'`);

observeApiError({ status: 503 }, mockObserver);
console.assert(lastCall === '5xx', `Expected '5xx', got '${lastCall}'`);

// Test no status (failure)
observeApiError({ message: 'no status' }, mockObserver);
console.assert(lastCall === 'failure', `Expected 'failure', got '${lastCall}'`);

// Test status < 400 (failure)
observeApiError({ status: 200 }, mockObserver);
console.assert(lastCall === 'failure', `Expected 'failure', got '${lastCall}'`);

observeApiError({ status: 0 }, mockObserver);
console.assert(lastCall === 'failure', `Expected 'failure', got '${lastCall}'`);

